void can_v_can_irq_service_rx (Can_IO_Base can_io_base)
{
  Can_Msg can_msg ;

  /*read_msg_to_ram :*/
    {
      can_msg_rd (can_io_base , & can_msg) ;    
    }

 /* service_can_v_rx_objects :*/
    {
      const Lut_Map * lut_map ;

      for (lut_map = can_v_vars.exec.lut_map_table [can_msg.lut_index_rx] ; lut_map ; lut_map = lut_map->next)
        {
          Rx_Q_Msg * rx_q_msg = (Rx_Q_Msg *) os_mbx_rcev_i (lut_map->can_v_rx->obj.exec.q_free) ;
        
          if (rx_q_msg)
            {
              rx_q_msg->can_msg              = can_msg            ;
              rx_q_msg->can_msg.lut_index_rx = lut_map->lut_index ;
        
              os_mbx_send_i (lut_map->can_v_rx->obj.exec.q_rcev , (MbxMsg *) rx_q_msg) ;
            }
        }
    }
}

